pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual
    // 2. Penalty for creating "dead zones": if post_residual is between 1 and 9, 
    // it's likely to be unusable for future items (since min size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Matching: If the post_residual can fit the next item, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it creates a "perfect fit" for the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 4. Global State Awareness:
    // If this is the only bin that can fit, we should prefer it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. New Bin Thresholding:
    // Only open a new bin (where bin_residual == bin_capacity) if the current 
    // best fit is very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost + normalized progress cost.
        // We only open a new bin if the existing bins are too full to accommodate 
        // the current item efficiently.
        score += 25.0 + (step_index as f64 / total_items as f64) * 10.0;
    }

    // 6. Mean Residual Balancing:
    // Penalize bins that deviate too far from the average residual to keep bins uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We aim to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (small unusable space < 10) that are harder to fill later.
    // We scale this penalty non-linearly with progress to be more aggressive as the stream ends.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + 2.0 * progress.powi(2));
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.5) * (1.0 - progress);
    }

    // Encourage filling existing bins rather than opening new ones when progress is high.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy progress-based penalty.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (bin_capacity as f64) * (0.5 + 0.5 * progress);
    }

    // Balance the distribution: if the bin residual is significantly above the mean,
    // we penalize it to force consolidation into tighter bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing.
    // However, protect 'perfect' fits (post_residual == 0) with a massive discount.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave residuals which are multiples of common item sizes (e.g., 20, 25, 33).
    // This encourages creating "clean" space for future items.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 1.5;

    // 3. Lookahead Synergy: If the next item fits into the post_residual, drastically reduce the score.
    // This implements a primitive Best-Fit-Decreasing-like lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0;
        // Further reward if the post-post residual is near zero (perfect pair fit).
        if (post_residual - next_item_size) < 5 {
            score -= 100.0;
        }
    }

    // 4. Scarcity Management: If this is the only bin that can fit the current item, 
    // prioritize it to avoid wasting the opportunity.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current residual options 
    // are extremely poor (i.e., leaving very small fragments that cannot fit typical items).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (to avoid fragmentation)
        // or if the current mean_residual is already quite high.
        score += 150.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Dynamic Scaling: As the stream progresses, favor tighter packing to clear out bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize bins that leave tiny, unusable fragments (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: Reward placements where post_residual perfectly accommodates next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for a tight fit for the next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.8;
        } else {
            // Penalty for stranding the next item (making it impossible to fit in this bin)
            score += 20.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid opening new bins if the current residual is close to the average
    // Encourages consolidating space to maintain a healthy mean_residual
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += mean_residual * 0.5;
        }
    } else {
        // Bias towards bins that keep the bin state near the global average
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // 4. Scarcity Handling: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Weighting: As the stream nears the end, prioritize tight packing more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residual (Best Fit principle)
    // We want to minimize the gap left behind.
    let mut score = post_res;

    // Non-linear interaction: Penalize creating a residual that cannot accommodate 
    // the next item, scaled by how far we are into the stream.
    // As we approach the end of the stream, we become more desperate to fit the next item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            // Penalty grows as we approach the end of the stream
            score += (next_item_size as f64 - post_res) * (1.0 + progress * 2.0);
        }
    }

    // Dynamic threshold: If we have many open bins, penalize opening a new one
    // unless the current fit is exceptionally good.
    if bin_residual == bin_capacity {
        // This is a new bin candidate
        if open_bins_count > 0 {
            // Penalize opening a new bin proportional to existing waste
            score += mean_residual * (1.0 - progress * 0.5);
            // Stronger penalty if we still have bins that can fit the item
            if fitting_bins_count > 0 {
                score += 50.0 * (1.0 - progress);
            }
        }
    } else {
        // If this is an existing bin, favor keeping the residual small but usable
        // Apply a non-linear curvature to discourage "near-empty" bins
        score += (100.0 - post_res).powf(1.1) * 0.05;
    }

    // Final scaling: discourage wasting space in early stages where we can afford 
    // to be more selective, but prioritize tight packing in late stages.
    score * (1.0 + progress * 0.2)
}
